def oracle2numpy(desc):
    or_n = 'or_n'
    or_f = 'or_f'
    or_s = 'or_s'

    name = desc[0]
    otype = desc[1]
    size = desc[3]
    digits = desc[4]
    scale = desc[5]

    if otype == or_n:
        if scale is None and digits is None:
            return "f8"
        if scale == 0 and digits != 0:
            if digits <= 4:
                return "i2"
            elif digits <= 9:
                return "i4"
            else:
                return "i8"
        else:
            if digits is None:
                return "f8"
            if digits <= 6:
                return "f4"
            elif digits <= 15:
                return "f8"
            else:
                return "f16"
    elif otype == or_f:
        if size == 4:
            return "f4"
        elif size == 8:
            return "f8"
    elif otype == or_s:
        return "S" + str(size)
    else:
        return ""

