def turn_sequence(move_list):
    u = [0,1]
    d = [0,-1]
    r = [1, 0]
    l = [-1, 0]
    turn_seq = ""
    for i, move in enumerate(move_list[:-1]):
        next_move = move_list[i+1]
        if move == next_move:
            turn_seq += "s"  # s for straight
        elif move == u and next_move == r:  # turned right
            turn_seq += "r"
        elif move == u and next_move == l:  # turned left
            turn_seq += "l"
        elif move == d and next_move == r:
            turn_seq += "l"
        elif move == d and next_move == l:
            turn_seq += "r"
        elif move == r and next_move == u:
            turn_seq += "l"
        elif move == r and next_move == d:
            turn_seq += "r"
        elif move == l and next_move == u:
            turn_seq += "r"
        elif move == l and next_move == d:
            turn_seq += "l"
    return turn_seq

def count_leading_digits_var2(numd):

    # Initialize the repartition by ones to avoid division by zero error further ahead
    f=[1, 1, 1, 1, 1, 1, 1, 1, 1]

    for i in numd:
        c = str(int(i))[0]
        if c == '1':
            f[0] += 1
        elif c == '2':
            f[1] += 1;
        elif c == '3':
            f[2] += 1;
        elif c == '4':
            f[3] += 1;
        elif c == '5':
            f[4] += 1;
        elif c == '6':
            f[5] += 1;
        elif c == '7':
            f[6] += 1;
        elif c == '8':
            f[7] += 1;
        elif c == '9':
            f[8] += 1;

    return f

def maximal_mesh_pattern_of_occurrence(perm, occ):

    k = len(occ)

    con = set(perm[i] for i in occ)
    colcnt = 0
    col = [-1] * len(perm)
    for v in perm:
        if v in con:
            colcnt += 1
        else:
            col[v] = colcnt
    rowcnt = 0
    row = [-1] * len(perm)
    for v in range(len(perm)):
        if v in con:
            rowcnt += 1
        else:
            row[v] = rowcnt
    # bad is the set of boxes that contain points and can not be shaded
    bad = set((u, v) for u, v in zip(col, row) if u != -1)
    # cur is the set of boxes that can be shaded
    cur = set((u, v) for u in range(k + 1) for v in range(k + 1) if (u, v) not in bad)
    return cur

