def oligo_complements(oligo):
    complement = ""
    reverse = ""
    reverse_complement = ""
    oligo2 = ""
    for ch in oligo:
        if ch == 'A':
            complement += 'T'
        elif ch == 'T' or ch == 'U':
            complement += 'A'
        elif ch == 'C':
            complement += 'G'
        elif ch == 'G':
            complement += 'C'
    for ch in oligo:
        if ch == 'U':
            oligo2 += 'T'
        else:
            oligo2 += ch

    i = len(oligo) - 1
    while i >= 0:
        reverse += oligo[i]
        reverse_complement += complement[i]
        i -= 1
    oligos = [oligo2, complement, reverse, reverse_complement]
    return oligos

