def change_display(data, mode):
    for i in range(len(data)):
        data[i] = int(data[i])
    if mode < 1 or mode > 20:
        return data
    if mode < 11:  # if in modes 1-10
        if mode < 6:
            for i in range(mode):
                data[i] += 64
        else:
            mode -= 5
            for i in range(5):
                data[i] += 64
            for i in range(mode):
                data[(i + 1) * -1] += 32

    else:  # if in modes 11-20
        mode -= 10  # avoid getting list index out of range
        if mode < 6:
            for i in range(5):
                data[i] += 32
            for i in range(5 - mode):
                data[(i + 1) * -1] += 64
        else:
            mode -= 5
            for i in range(5 - mode):
                data[i] += 32

    return data

