def _piecewise(a):
        b = [
            (
                a[2 * i]
                .replace("小于", "")
                .replace("大于", "")
                .replace("等于", "")
                .replace("个", "")
            ).split("，")
            for i in range(int(len(a) / 2))
        ]
        for j, tem in enumerate(b):
            for i, num in enumerate(tem):
                if num[-1] == "天":
                    num = int(num[:-1])
                elif num[-1] == "月":
                    num = int(num[:-1]) * 30
                else:
                    num = int(num[:-1]) * 365
                b[j][i] = num
        if len(b[0]) == 1:  # 有时赎回费会写大于等于一天
            b[0].insert(0, 0)
        elif len(b[0]) == 2:
            b[0][0] = 0
        else:
            print(_warnmess)
        for i in range(len(b) - 1):  # 有时赎回费两区间都是闭区间
            if b[i][1] - b[i + 1][0] == -1:
                b[i][1] = b[i + 1][0]
