def convolution_size(
    given_size, num_layers, kernel_sizes, padding=0, strides=1, dilations=1,
    inverse=False
):
    if type(kernel_sizes) is int:
        kernel_sizes = [kernel_sizes] * num_layers
    else:
        assert len(kernel_sizes) == num_layers
    if type(padding) is int:
        padding = [padding] * num_layers
    else:
        assert len(padding) == num_layers
    if type(strides) is int:
        strides = [strides] * num_layers
    else:
        assert len(strides) == num_layers
    if type(dilations) is int:
        dilations = [dilations] * num_layers
    else:
        assert len(dilations) == num_layers

    size = given_size

    if not inverse:
        for i in range(num_layers):
            size = int(
                (size + (2 * padding[i]) - (dilations[i] * (kernel_sizes[i] - 1)) \
                 - 1) / strides[i]
            ) + 1
    else:
        for i in range(num_layers - 1, -1, -1):
            size = (strides[i] * (size - 1)) - (2 * padding[i]) + \
                   (dilations[i] * (kernel_sizes[i] - 1)) + 1
    return size

def rformat(obj, indent=0, name=None, width=90, **kArgs):
  #print(" kArgs: %s" % kArgs)
  try:
    kArgs['depth'] -= 1
  except:
    kArgs['depth'] = 100
  if kArgs['depth']==0: 
    print(indent*"  "+"...")
    return


  ss = repr(obj)
  if len(ss)<width-indent*2:
    #print("%s --%d %s" % (name, len(ss), ss))
    ss = indent*"  "+ss

  else:  # expression is too long, break it down
    ss = ""
    objType = type(obj)
    #print("%s ++%s" % (name, str(objType)))
    if objType==list:
      ss = ""
      for it in obj:
        ss += rformat(it, indent+1, width=width, **kArgs)+',\n'
      if ss[-2:] == ",\n":  ss = ss[:-2]+'\n'
      ss = indent*"  "+"[\n"+ ss +indent*"  "+"]"

    elif objType==tuple:
      ss += indent*"  "+"(\n"
      for it in obj:
        ss += rformat(it, indent+1, width=width, **kArgs)+',\n'
      if ss[-2:] == ",\n":  ss = ss[:-2]+'\n'
      ss += indent*"  "+")"

    elif objType==dict or objType==bunch: # or objType==bun:
      if objType==dict:
        startTag = "{";  sep = ":";  endTag = "}"
      else:
        startTag = "bunch(";  sep = "=";  endTag = ")"

      ss += indent*"  "+startTag+"\n"
      for it in obj:
        ss += indent*"  "+"  "+str(it)+sep+" "+rformat(obj[it],
          indent+1, name=it, width=width, **kArgs).strip()+',\n'
      if ss[-2:] == ",\n":  ss = ss[:-2]+'\n'
      ss += indent*"  "+endTag
    else:    
      ss += indent*"  "+repr(obj)
  return ss

def __to_matrix(lst, column_size):
    l_length = len(lst)
    if not column_size or column_size >= l_length:
        return [lst]

    if column_size == 1:
        row_size = l_length
    elif l_length // column_size == 1:
        row_size = 2
    else:  # top row + bottom row + side columns in between
        row_size = ((l_length - 2 * column_size + 1) // 2 + 2)
    matrix = [[" "] * column_size for j in range(row_size)]

    current_row = 0
    current_col = 0
    direction = "right"  # "right", "down", "left", "up"
    for e in lst:
        # top row
        if direction == "right":
            if current_col <= column_size - 1:
                matrix[current_row][current_col] = e
                current_col += 1
            if current_col >= column_size:
                current_col = column_size - 1
                current_row += 1
                direction = "down" if row_size > 2 else "left"
            continue
        # right column
        elif direction == "down":
            if current_row < row_size - 1:
                matrix[current_row][current_col] = e
                current_row += 1
            if current_row >= row_size - 1:
                current_row = row_size - 1
                direction = "left"
            continue
        # bottom row
        elif direction == "left":
            if current_col >= 0:
                matrix[current_row][current_col] = e
                current_col -= 1
            if current_col < 0:
                current_col = 0
                current_row = row_size - 2
                direction = "up"
            continue
        # left column
        elif direction == "up":
            if current_row >= 1:
                matrix[current_row][current_col] = e
                current_row -= 1
            if current_row == 0:
                break
    return matrix

