def find_gridsize(row):
    y = 0
    min_y = 0
    max_y = 0
    x = 0
    min_x = 0
    max_x = 0

    for item in row:
        if item[0] == 'D':
            y -= int(item[1:])
            if y < min_y: min_y = y
        elif item[0] == 'U':
            y += int(item[1:])
            if y > max_y: max_y = y
        elif item[0] == 'L':
            x -= int(item[1:])
            if x < min_x: min_x = x
        elif item[0] == 'R':
            x += int(item[1:])
            if x > max_x: max_x = x
        else: print('ERROR - should never reach this')
    return min_y, max_y, min_x, max_x

