def updateRHS(vname, expr, i='i', j='j', k='k', update=False, updateq=False, rhs=None):
    varname = {'velocity': 'rhs_x', 'pressure': 'rhs_y', 'temperature': 'rhs_z'}
    dim = 3 if rhs == 'rhs_z' else 2 if rhs == 'rhs_y' else 1

    if dim == 3:
        rhs_expr = 'rhs('+i+','+j+','+k+',indvars('+str(varname[vname])+'))'
    elif dim == 2:
        rhs_expr = 'rhs('+i+','+j+',indvars('+str(varname[vname])+'))'
    elif dim == 1:
        rhs_expr = 'rhs('+i+',indvars('+str(varname[vname])+'))'

    if not update:
        out = rhs_expr + ' = ' + ' ' + expr
    else:
        out = rhs_expr + ' = ' + rhs_expr + ' ' + expr

    if updateq:
        if dim == 3:
            q = 'q('+i+','+j+','+k+',indvars('+str(varname[vname])+'))'
        elif dim == 2:
            q = 'q('+i+','+j+',indvars('+str(varname[vname])+'))'
        elif dim == 1:
            q = 'q('+i+',indvars('+str(varname[vname])+'))'

        if not update:
            out = q + ' = ' + ' ' + expr
        else:
            out = q + ' = ' + q + ' ' + expr

    return out

WHITE = 0
BLACK = 1
EITHER = 2

def simple_filler(arr, runs):
    k = 0  # index for runs
    on_black = 0
    allowed = arr[:]
    for i in range(len(arr)):
        if arr[i] == WHITE:
            if on_black > 0:
                k += 1  # move to the next pattern
            on_black = 0
        elif arr[i] == BLACK:
            on_black += 1
        else:  # arr[i] == EITHER
            if k >= len(runs):
                break
            elif 0 < on_black < runs[k]:  # this must be part of this sequence
                allowed[i] = BLACK
                on_black += 1
            elif on_black == 0 and k > 0 and i > 0 and arr[i - 1] == BLACK:  # this must be a white ending a sequence
                allowed[i] = WHITE
            else:
                break  # too many unknowns

    # put whites next to any 1 runs. Very special case
    if all([r == 1 for r in runs]):
        for i in range(len(arr)):
            if arr[i] == BLACK:
                if i > 0:
                    allowed[i - 1] = WHITE
                if i < len(arr) - 1:
                    allowed[i + 1] = WHITE

    return allowed

