def local_computecov(start_list, end_list, local_entry):
        ret_cov = 0
        Ls = local_entry[0]
        Le = local_entry[1]
        for Ts, Te in zip(start_list, end_list):
            if Ls > Ts and Ls < Te and Le > Ts and Le < Te:
                # in
                ret_cov += Le - Ls
            if Ls < Ts and Ls < Te and Le > Ts and Le < Te:
                # start out
                ret_cov += Le - Ts
            if Ls > Ts and Ls < Te and Le > Ts and Le > Te:
                # end out
                ret_cov += Te - Ls
            if Ls < Ts and Ls < Te and Le > Ts and Le > Te:
                # start&end out
                ret_cov += Te - Ts
        return (ret_cov)

def calcfwhm(x,y):
	ymin,ymax = min(y),max(y)
	y_hpeak = ymin + .5 *(ymax-ymin)
	x_hpeak = []
	NPT = len(x)
	for i in range(NPT):
		if y[i] >= y_hpeak:
			i1 = i
			break
	for i in range(i1+1,NPT):
		if y[i] <= y_hpeak:
			i2 = i
			break
		if i == NPT-1: i2 = i
	if y[i1] == y_hpeak: x_hpeak_l = x[i1]
	else:
		x_hpeak_l = (y_hpeak-y[i1-1])/(y[i1]-y[i1-1])*(x[i1]-x[i1-1])+x[i1-1]
	if y[i2] == y_hpeak: x_hpeak_r = x[i2]
	else:
		x_hpeak_r = (y_hpeak-y[i2-1])/(y[i2]-y[i2-1])*(x[i2]-x[i2-1])+x[i2-1]
	x_hpeak = [x_hpeak_l,x_hpeak_r]

	fwhm = abs(x_hpeak[1]-x_hpeak[0])
	for i in range(NPT):
		if y[i] == ymax: 
			jmax = i
			break
	xpeak = x[jmax]
	return (fwhm,xpeak,ymax)

