import random

def ball_movement(vertical_direct, horizontal_direct, collision=False, out=False):
    global x_change, y_change
    ball = {'x': 0, 'y': 0}  # Initialize ball position
    ver = vertical_direct
    hor = horizontal_direct
    y_change = 10  # Define y_change
    x_change = 10  # Define x_change
    if vertical_direct == 'up':
        if ball['y'] - y_change > 0:
            ball['y'] -= y_change
        else:
            if collision:
                change = random.choice((4, -4))
                if change == 4:
                    if y_change + change < 14:
                        y_change += change
                else:
                    if y_change + change < 6:
                        y_change += change
                ver = 'down'
    else:
        if ball['y'] + y_change < 700:
            ball['y'] += y_change
        else:
            if collision:
                change = random.choice((4, -4))
                if change == 4:
                    if y_change + change < 14:
                        y_change += change
                else:
                    if y_change + change < 6:
                        y_change += change
                ver = 'up'

    if horizontal_direct == 'left':
        if ball['x'] + x_change < 970:
            ball['x'] += x_change
        else:
            if collision:
                change = random.choice((4, -4))
                if change == 4:
                    if y_change + change < 14:
                        y_change += change
                else:
                    if y_change + change < 6:
                        y_change += change
                hor = 'right'
            else:
                out = True
    else:
        if ball['x'] - x_change > 0:
            ball['x'] -= x_change
        else:
            if collision:
                change = random.choice((4, -4))
                if change == 4:
                    if y_change + change < 14:
                        y_change += change
                else:
                    if y_change + change < 6:
                        y_change += change
                hor = 'left'
            else:
                out = True
    return ver, hor, out

