from typing import List, Tuple

def follow_movements(instructions: List[str]) -> Tuple[int, int]:
    start = 0j
    heading = 1
    for line in instructions:
        direction = line[0]
        amount = int(line[1:])
        if direction == "F":
            start += heading * amount
        elif direction == "N":
            start += 1j * amount
        elif direction == "S":
            start += -1j * amount
        elif direction == "E":
            start += amount
        elif direction == "W":
            start -= amount
        elif direction == "L":
            if amount not in {0, 90, 180, 270}:
                raise ValueError(f"unknown turn left amount {amount}")
            while amount > 0:
                heading *= 1j
                amount -= 90
        elif direction == "R":
            if amount not in {0, 90, 180, 270}:
                raise ValueError(f"unknown turn right amount {amount}")
            while amount > 0:
                heading *= -1j
                amount -= 90
        else:
            raise ValueError(f"unknown command {line}")
    return int(start.real), int(start.imag)

