from typing import List, Optional

def compute_right(k: int, word: List[int]) -> List[Optional[int]]:
    w = word
    curr_cont: List[int] = [0 for _ in range(max(w) + 1)]
    curr_k: int = 0
    right_k: List[Optional[int]] = [None for _ in range(len(w))]
    j: int = -1
    for i in range(len(w)):
        if i > 0:
            curr_cont[w[i - 1]] -= 1
            if curr_cont[w[i - 1]] == 0:
                curr_k -= 1
        while j < len(w) - 1 and (curr_cont[w[j + 1]] != 0 or curr_k < k):
            j += 1
            if curr_cont[w[j]] == 0:
                curr_k += 1
            curr_cont[w[j]] += 1
        if curr_k == k:
            right_k[i] = j
    return right_k

