def find_integers(m1, m2, m3, g23, g12, g31, g123):
    # Compute p (it's a modulo equation)
    if g23 == 1:
        p = 0
    else:
        p = None
        for i in range(0, g23):
            if (m2 + i * m3) % g23 == 0:
                p = i
                break
        if p is None:
            p = 0
    # Compute q
    g12_r = g12 // g123
    g23_r = g23 // g123
    g31_r = g31 // g123
    if g12_r == 1:
