def rare_second_digits(first, last):

    if first == 2 or (first == 8 and last == 8):
        for n in range(10):
            yield (n, n)
    elif first == 4:
        for a in range(0, 10):
            for b in range((0 if a % 2 == 0 else 1), 10, 2):
                yield (a, b)
    elif first == 6:
        for a in range(0, 10):
            for b in range((1 if a % 2 == 0 else 0), 10, 2):
                yield (a, b)
    elif first == 8:
        if last == 2 or last == 8:
            for a in range(0, 10):
                yield (a, 9-a)
        elif last == 3:
            for a in range (0, 10):
                if a > 6:
                    yield (a, a-7)
                else:
                    yield (a, a+3)
        elif last == 7:
            for a in range(0, 10):
                if a > 1:
                    yield (a, 11-a)
