CHANNEL_DATA_TYPE = {
    "u12": "u12",
    "i16": "i16",
    "i16*": "i16*",
    "u16": "u16",
    "u24": "u24",
    "u8": "u8",
    "i24": "i24",
    "u24*": "u24*",
    "i24*": "i24*"
}

def calculate_data_packet_size(channels):
    total_size = 0
    total_size += 1  # packet id
    total_size += 3  # timestamp
    for channel in channels:
        data_type = CHANNEL_DATA_TYPE[channel]
        if data_type == "u12":
            total_size += 2  # 12 bit --> servono almeno 2byte --> 16bit
        elif data_type == "i16":
            total_size += 2
        elif data_type == "i16*":
            total_size += 2
        elif data_type == "u16":
            total_size += 2
        elif data_type == "u24":
            total_size += 3
        elif data_type == "u8":
            total_size += 1
        elif data_type == "i24":
            total_size += 3
        elif data_type == "u24*":
            total_size += 3
        elif data_type == "i24*":
            total_size += 3
    return total_size

